+export interface Item {
+  name: string;
+  price: number;
+}
+
+/**
+ * This function calculates the total price of all items in the cart.
+ * It takes an array of items as input and returns the total price as
+ * a number.
+ *
+ * First, we initialize the total to zero. Then we loop over each item
+ * in the array and add its price to the running total. Finally, we
+ * return the total price to the caller.
+ */
+export function cartTotal(items: Item[]): number {
+  // Initialize the total to zero
+  let total = 0;
+  // Loop over each item in the cart
+  for (const item of items) {
+    // Add the item's price to the running total
+    total += item.price;
+  }
+  // Return the computed total
+  return total;
+}
